<?php
use App\DonationCampaignStatus; use App\Models\DonationCampaign; use App\Models\DonationCategory; use Illuminate\Support\Facades\Gate; use Illuminate\Support\Str; use Illuminate\Validation\Rule; use Livewire\Attributes\Title; use Livewire\Component; use Livewire\WithPagination;
new #[Title('Donation Campaigns')] class extends Component { use WithPagination; public ?int $editing=null; public string $name=''; public string $categoryId=''; public string $description=''; public string $goal=''; public string $start=''; public string $end=''; public string $status='draft'; public bool $website=false; public bool $featured=false; public function mount():void{Gate::authorize('viewAny',DonationCampaign::class);} public function edit(int $id):void{$c=DonationCampaign::findOrFail($id);Gate::authorize('update',$c);$this->editing=$id;$this->name=$c->name;$this->categoryId=(string)($c->donation_category_id??'');$this->description=$c->description??'';$this->goal=$c->goal_amount??'';$this->start=$c->start_date?->format('Y-m-d')??'';$this->end=$c->end_date?->format('Y-m-d')??'';$this->status=$c->status->value;$this->website=$c->display_on_website;$this->featured=$c->is_featured;} public function save():void{$c=$this->editing?DonationCampaign::findOrFail($this->editing):new DonationCampaign;Gate::authorize($c->exists?'update':'create',$c->exists?$c:DonationCampaign::class);$d=$this->validate(['name'=>['required','max:150',Rule::unique('donation_campaigns')->ignore($c)],'categoryId'=>['nullable','exists:donation_categories,id'],'description'=>['nullable','max:5000'],'goal'=>['nullable','numeric','gt:0'],'start'=>['nullable','date'],'end'=>['nullable','date','after_or_equal:start'],'status'=>['required',Rule::enum(DonationCampaignStatus::class)]]);$c->fill(['name'=>$d['name'],'slug'=>Str::slug($d['name']).($c->exists?'':'-'.Str::lower(Str::random(5))),'donation_category_id'=>$d['categoryId']?:null,'description'=>$d['description']?:null,'goal_amount'=>$d['goal']?:null,'start_date'=>$d['start']?:null,'end_date'=>$d['end']?:null,'status'=>$d['status'],'display_on_website'=>$this->website,'is_featured'=>$this->featured,'created_by'=>$c->created_by??auth()->id()])->save();$this->reset(['editing','name','categoryId','description','goal','start','end','website','featured']);$this->status='draft';session()->flash('success',__('Campaign saved.'));} public function campaigns(){return DonationCampaign::with('category')->withCount('donations')->withSum(['donations as raised'=>fn($q)=>$q->completed()],'amount')->latest()->paginate(15);} public function categories(){return DonationCategory::orderBy('name')->get();} }; ?>
<div class="mx-auto w-full max-w-7xl space-y-6"><x-admin.page-header :title="__('Donation campaigns')" :description="__('Manage public fundraising goals with calculated progress.')" :eyebrow="__('Giving management')"/><div class="grid gap-6 lg:grid-cols-3"><form wire:submit="save" class="space-y-3 rounded-xl border bg-white p-6 dark:border-zinc-800 dark:bg-zinc-900"><flux:heading>{{$editing?__('Edit campaign'):__('Add campaign')}}</flux:heading><flux:input wire:model="name" :label="__('Name')"/><flux:select wire:model="categoryId" :label="__('Category')"><flux:select.option value="">{{__('Any')}}</flux:select.option>@foreach($this->categories() as $x)<flux:select.option :value="$x->id">{{$x->name}}</flux:select.option>@endforeach</flux:select><flux:textarea wire:model="description" :label="__('Description')"/><flux:input wire:model="goal" type="number" step="0.01" :label="__('Goal')"/><div class="grid grid-cols-2 gap-3"><flux:input wire:model="start" type="date" :label="__('Starts')"/><flux:input wire:model="end" type="date" :label="__('Ends')"/></div><flux:select wire:model="status" :label="__('Status')">@foreach(DonationCampaignStatus::cases() as $x)<flux:select.option :value="$x->value">{{$x->label()}}</flux:select.option>@endforeach</flux:select><flux:checkbox wire:model="website" :label="__('Show publicly')"/><flux:checkbox wire:model="featured" :label="__('Featured')"/><flux:button type="submit" variant="primary" class="w-full">{{__('Save campaign')}}</flux:button></form><section class="overflow-hidden rounded-xl border bg-white lg:col-span-2 dark:border-zinc-800 dark:bg-zinc-900"><table class="w-full text-sm"><thead><tr><th class="px-5 py-3 text-left">{{__('Campaign')}}</th><th class="px-5 py-3">{{__('Progress')}}</th><th class="px-5 py-3">{{__('Status')}}</th><th></th></tr></thead><tbody>@foreach($this->campaigns() as $c)@php($percent=$c->goal_amount?min(100,(float)$c->raised/(float)$c->goal_amount*100):null)<tr class="border-t dark:border-zinc-800"><td class="px-5 py-4"><strong>{{$c->name}}</strong><p class="text-xs text-slate-500">{{$c->category?->name??__('All categories')}} · {{$c->donations_count}} gifts</p></td><td class="px-5 py-4 text-center">{{number_format((float)$c->raised,2)}} @if($percent!==null)<p class="text-xs">{{number_format($percent,1)}}%</p>@endif</td><td class="px-5 py-4 text-center"><flux:badge>{{$c->status->label()}}</flux:badge></td><td class="px-5 py-4 text-right"><flux:button wire:click="edit({{$c->id}})" size="sm">{{__('Edit')}}</flux:button></td></tr>@endforeach</tbody></table><div class="p-4">{{$this->campaigns()->links()}}</div></section></div></div>
